CREATE INDEX IF NOT EXISTS idx_floor_orders_store_opened
    ON floor_orders (company_id, store_id, opened_at DESC);
CREATE INDEX IF NOT EXISTS idx_floor_order_payments_paid_at
    ON floor_order_payments (paid_at DESC);
CREATE INDEX IF NOT EXISTS idx_floor_reservations_store_created
    ON floor_reservations (company_id, store_id, created_at DESC);
